typedef float rational_t;
typedef float time_value_t;

class entity;
class entity_track_tree;
class po_anim;
class signal_anim;

class stringx {
    int value;
public:
    stringx();
};

class quaternion {
public:
    float a, b, c, d;
    quaternion() { a = 1.0f; b = c = d = 0.0f; }
};

class vector3d {
public:
    float x, y, z;
    vector3d() {}
};

class entity_anim {
protected:
    unsigned short flags;
    unsigned short pad;
public:
    virtual ~entity_anim();
protected:
    entity *ent;
    po_anim *po_anim_ptr;
    signal_anim *signal_anim_ptr;
    int priority;
    quaternion tween_quat;
    vector3d rel_pos;
public:
    rational_t floor_offset;
    entity_anim(entity *_ent)
    : ent(_ent), po_anim_ptr(0), signal_anim_ptr(0), floor_offset(0) {}
};

struct pentity_anim_vector {
    entity_anim **start;
    entity_anim **finish;
    entity_anim **end;
};

struct anim_control_t { char data[36]; };

extern pentity_anim_vector *entity_anim_tree_anims;
extern int current_allocation;

class entity_anim_tree : public entity_anim {
    stringx name;
    const entity_track_tree *track;
    rational_t blend_a;
    anim_control_t control;
    pentity_anim_vector &anims;
    rational_t floor_offset;
    const entity_track_tree *trackb;
    rational_t blend_b;
    pentity_anim_vector anims_b;
    anim_control_t control_b;
public:
    entity_anim_tree(const stringx& _name, entity* _ent,
                     const entity_track_tree& _tracka,
                     const entity_track_tree& _trackb,
                     rational_t blenda, rational_t blendb,
                     unsigned short anim_flags = 0,
                     time_value_t start_time = 0,
                     int _priority = 0, short loop = -1);
    virtual ~entity_anim_tree();
    void construct(const stringx& _name, const entity_track_tree& _tracka,
                   const entity_track_tree& _trackb,
                   rational_t blenda, rational_t blendb,
                   unsigned short anim_flags, time_value_t start_time,
                   int _priority, short loop);
};

__asm__(".equ __vt_11entity_anim, 0x004BA170");
__asm__(".equ __vt_16entity_anim_tree, 0x004BA120");
__asm__(".equ __7stringx, 0x0034D3E0");
__asm__(".equ construct__16entity_anim_treeRC7stringxRC17entity_track_treeT2ffUsfis, 0x001167D8");
__asm__(".equ entity_anim_tree_anims, 0x003E5848");
__asm__(".equ current_allocation, 0x003E5758");

entity_anim_tree::entity_anim_tree( const stringx& _name,
                                    entity* _ent,
                                    const entity_track_tree& _tracka,
                                    const entity_track_tree& _trackb,
                                    rational_t blenda,
                                    rational_t blendb,
                                    unsigned short anim_flags,
                                    time_value_t start_time,
                                    int _priority,
                                    short loop )
: entity_anim( _ent )
, anims ( entity_anim_tree_anims[current_allocation] )
{
  construct( _name, _tracka, _trackb, blenda, blendb, anim_flags, start_time, _priority, loop );
}
